css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .56); position: relative; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: calc(var(--loader-size) * .04); border-radius: 999px; background: color-mix(in srgb, #000 42%, var(--accent-2)); }
.loader span { position: absolute; bottom: calc(var(--loader-size) * .04); left: 7%; border-radius: 46%; background: linear-gradient(color-mix(in srgb, #fff 58%, var(--accent-2)), color-mix(in srgb, #fff 24%, var(--accent-2))); animation: flatten calc(var(--loader-speed) * 2.8) ease-in-out infinite; }
.loader .pin { position: absolute; left: 3%; width: 50%; height: calc(var(--loader-size) * .13); border-radius: 999px; background: repeating-linear-gradient(90deg, color-mix(in srgb, #fff 34%, var(--accent)) 0 calc(var(--loader-size) * .028), var(--accent) calc(var(--loader-size) * .028) calc(var(--loader-size) * .056)); background-size: calc(var(--loader-size) * .056) 100%; box-shadow: inset 0 calc(var(--loader-size) * -.022) calc(var(--loader-size) * .03) rgba(15, 23, 42, .3), inset 0 calc(var(--loader-size) * .014) calc(var(--loader-size) * .02) rgba(255, 255, 255, .35); animation: roll-pin calc(var(--loader-speed) * 2.8) ease-in-out infinite, pin-surface calc(var(--loader-speed) * .45) linear infinite; }
.loader .pin::before, .loader .pin::after { content: ''; position: absolute; top: 26%; width: calc(var(--loader-size) * .07); height: 48%; border-radius: 999px; background: color-mix(in srgb, #000 30%, var(--accent)); }
.loader .pin::before { left: calc(var(--loader-size) * -.055); }
.loader .pin::after { right: calc(var(--loader-size) * -.055); }
@keyframes flatten { 0%, 10% { width: 28%; height: calc(var(--loader-size) * .14); } 60% { width: 76%; height: calc(var(--loader-size) * .055); } 88%, 100% { width: 28%; height: calc(var(--loader-size) * .14); } }
@keyframes roll-pin { 0%, 10% { bottom: calc(var(--loader-size) * .19); transform: translateX(0); } 60% { bottom: calc(var(--loader-size) * .1); transform: translateX(calc(var(--loader-size) * .42)); } 88%, 100% { bottom: calc(var(--loader-size) * .19); transform: translateX(0); } }
@keyframes pin-surface { to { background-position: calc(var(--loader-size) * .056) 0; } }
